                  className='game__button'
                  type='button'
                  onClick={this.handleClickDismissError}
                >
                  OK
                </button>
              </p>
            </>
          )}

          {!error.dismissable && (
            <>
              <h3 style={{ fontWeight: 'bold' }}>To fix this</h3>
              <p>Report this problem to qntm.</p>
            </>
          )}
        </div>
