import assert from 'node:assert/strict'
import { describe, it } from 'node:test'

import hatetrisReplayCodec from '../../src/replay-codecs/hatetris-replay-codec.ts'

describe('hatetrisReplayCodec', () => {
  it('encodes', () => {
    assert.equal(hatetrisReplayCodec.encode(['D', 'D', 'D', 'R', 'U', 'D']), 'ਹԇ')
  })

  it('decodes', () => {
    assert.deepEqual(hatetrisReplayCodec.decode('A9E'), ['D', 'D', 'D', 'R', 'U', 'D'])
    assert.deepEqual(hatetrisReplayCodec.decode('𤺤'), ['D', 'D', 'D', 'R', 'U', 'D'])
    assert.deepEqual(hatetrisReplayCodec.decode('ਹԇ'), ['D', 'D', 'D', 'R', 'U', 'D'])
  })

  it('decodes with spaces', () => {
    assert.deepEqual(hatetrisReplayCodec.decode(' A9E'), ['D', 'D', 'D', 'R', 'U', 'D'])
    assert.deepEqual(hatetrisReplayCodec.decode('𤺤 '), ['D', 'D', 'D', 'R', 'U', 'D'])
    assert.deepEqual(hatetrisReplayCodec.decode(' ਹԇ '), ['D', 'D', 'D', 'R', 'U', 'D'])
  })

  // Due to padding, a replay (which always ends with a "D" instruction) sometimes has an
  // additional trailing "L" or "D"
  describe('known replays', () => {
    const runs = [{
      expectedDecoded: /^DDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDLD?$/,
      name: 'qntm',
      replays: {
        hex: 'AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA A2',
        Base65536: '𤆻𤆻𤆻𤆻𤆻𡚻',
        Base2048: '௨ටໃݹ௨ටໃݹठ'
